/**
 * App / favicon / PWA icons: the black MultiFrame logo on a white square.
 * Files live in public/ and are generated by scripts/generate-icons.py.
 * Shared by vite.config.ts (manifest + precache) and the icons spec.
 */
export type ManifestIcon = {
  src: string;
  sizes: string;
  type: string;
  purpose: 'any' | 'maskable';
};

export const MANIFEST_ICONS: ManifestIcon[] = [
  { src: 'favicon-64.png', sizes: '64x64', type: 'image/png', purpose: 'any' },
  { src: 'icon-128.png', sizes: '128x128', type: 'image/png', purpose: 'any' },
  { src: 'icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
  { src: 'icon-256.png', sizes: '256x256', type: 'image/png', purpose: 'any' },
  { src: 'icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
  { src: 'icon-maskable-192.png', sizes: '192x192', type: 'image/png', purpose: 'maskable' },
  { src: 'icon-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
];

